const e="Admission Policy and Entrance Requirements",t={verified:!1,lastEdited:"9/6/2026",branch:"main",tablesPresent:0,tablesConsumed:0,tablesOnPage:0,tablesExcluded:0,sourceUrl:"https://catalog.northeastern.edu/undergraduate/admission/admission-policy-entrance-requirements/",panes:[""],planOfStudyCourses:[],verification:{level:"partial",kind:"major",score:.68,checkedAt:"2026-09-07",sourceUrl:"https://catalog.northeastern.edu/undergraduate/admission/admission-policy-entrance-requirements/",sourcesAvailable:["requirement-tables","course-catalog"],counters:{tablesUnaccounted:0,leakedMarkers:0,unenumeratedSections:2,duplicateSectionTitles:0,duplicateConcentrationTitles:0,zeroTotal:1,unknownCourses:0,planUnexplained:0,impossibleSections:0},discrepancies:[{check:"missing-total-credits",severity:"medium",message:"the catalog page states no total credit requirement",detail:[{key:"noTotal"}],overflow:0},{check:"no-sample-plan",severity:"medium",message:"this program publishes no sample four-year plan, so our strongest check could not run",detail:[{key:"noPlanUnusual"}],overflow:0},{check:"unenumerated-sections",severity:"info",message:"2 section(s) state a credit requirement whose courses the catalog does not list, so completion of those cannot be checked automatically",detail:[{key:"unenumeratedSection",params:{title:"Transfer Credit",sh:60}},{key:"unenumeratedSection",params:{title:"Advanced Standing",sh:32}}],overflow:0}]}},r=0,a=2027,o=[{type:"SECTION",title:"Transfer Credit",creditsRequired:60,minRequirementCount:1,requirements:[],notes:["Students may transfer up to 60 semester hours of credit from a two-year college, or up to 80 semester hours from a four-year college, or a combination of the two types of colleges. If you have been admitted to the D’Amore-McKim School of Business and your college or university is not AACSB-accredited, the maximum number of credits that you can transfer to Northeastern is 60. See also Residency Requirement.","College courses completed with a grade of C or better are considered for transfer credit by faculty evaluators. Liberal arts coursework taken more than 10 years ago and math and science coursework completed more than 5 years ago cannot be considered.","All transfer-credit documents should be received prior to matriculation and must be received within one semester of matriculation. These documents include, but are not limited to, Advanced Placement, International Baccalaureate, and International Matriculation Exam scores and official transcripts from colleges and universities. These documents should be submitted whether or not you wish to receive transfer credit from this work. Transfer credit will not be granted for work completed prior to matriculation if the official credential is received after the completion of the first semester. College coursework completed at an international institution must be translated into English and evaluated by a recognized credential agency."]},{type:"SECTION",title:"Advanced Standing",creditsRequired:32,minRequirementCount:1,requirements:[],notes:["Results from your AP exams, IB exams, and other international matriculation examinations (listed below) may enable you to receive advanced credits. You may also receive transfer credit if you successfully completed accredited college-level courses that were taken while you were in high school, before you enrolled at Northeastern. You may apply up to 32 semester hours of advanced credit toward your undergraduate degree. For consideration, you must submit official transcripts or test results before matriculation and must submit official score reports for credit.","Northeastern currently awards advanced credit for the following examinations:","Additionally, if you completed a Diplôme d'études collégiales through a Collège d'enseignement général et professionnel in Quebec, you can apply up to 32 semester hours of transfer credit to your undergraduate degree. Northeastern will consider courses with grades equivalent to C or higher on the U.S. grading scale in courses completed in the second year. You can review the Transfer Equivalency Database to determine which courses will transfer to Northeastern. Any course not listed in the database has not yet been evaluated. Once admitted, you can submit full syllabi through your Application Status Check for the academic departments to review and determine any transfer credit."]}],n={name:e,metadata:t,totalCreditsRequired:r,yearVersion:a,requirementSections:o};export{n as default,t as metadata,e as name,o as requirementSections,r as totalCreditsRequired,a as yearVersion};
